set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'installer for tool 1.0' > site/tool-1.0.bin
cat > fetch-verified.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Downloads a URL and keeps it only if its SHA-256 is the published one.
# Usage: sh fetch-verified.sh <url> <published sha-256> <file>
url=$1 want=$2 file=$3
curl -fsS -o "$file.part" "$url" || exit
if command -v sha256sum >/dev/null; then got=$(sha256sum "$file.part")
else got=$(shasum -a 256 "$file.part"); fi
got=${got%% *}
if [ "$got" != "$want" ]; then
  rm -f "$file.part"
  echo "refused $file: SHA-256 is $got, not $want" >&2
  exit 1
fi
mv "$file.part" "$file"
echo "kept $file: SHA-256 $got"
EOF
surl --directory site http://127.0.0.1:8080/ &
sleep 1
sh fetch-verified.sh http://127.0.0.1:8080/tool-1.0.bin 0e2fb8e221331b806feda5547ebd3fa59614053f86f9f0d92b8e840976e0e80c tool-1.0.bin
kill $(jobs -p)
